    let registry = RegistryBindingId::new("cratesIo", RegistryBindingDigest::parse(&"b".repeat(64)).unwrap()).unwrap();
    let publish = ReleaseOperation::registry_publish(package.clone(), version.clone(), registry, vec![]).unwrap();
