fn guard_flags_a_snake_case_key_at_depth() {
    let caught = std::panic::catch_unwind(|| {
        assert_no_snake_case_keys("probe", &json!({"a": [{"kind": "x", "short_sha": "y"}]}));
    });
    assert!(caught.is_err());
}
